<?php
// Area guide download (generated by tools/build_guides.py).
// The PDF is only sent after the enquiry form is submitted: ../downloads/guides/ is closed to direct
// visits by its .htaccess. The enquiry goes to the same Google Sheet / Telegram as the Quick Enquiry.
header('X-Robots-Tag: noindex, nofollow');
if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') { http_response_code(405); header('Content-Type: text/plain; charset=utf-8'); exit('Please use the form on the guide page.'); }
function kn_f($k, $n = 200) { return trim(mb_substr((string)($_POST[$k] ?? ''), 0, $n)); }
function kn_fail($code, $msg) { http_response_code($code); header('Content-Type: text/plain; charset=utf-8'); exit($msg); }
$slug  = preg_replace('/[^a-z0-9-]/', '', kn_f('slug', 80));
$file  = __DIR__ . '/../downloads/guides/' . $slug . '.pdf';
$name  = kn_f('name', 120);
$email = kn_f('email', 160);
$code  = preg_replace('/[^0-9+]/', '', kn_f('code', 8));
$phone = preg_replace('/[^0-9 +\-]/', '', kn_f('phone', 30));
$wc    = kn_f('wc', 80);
$area  = kn_f('area', 80);
if ($slug === '' || !is_file($file)) kn_fail(404, 'Guide not found.');
if (kn_f('hp') !== '') kn_fail(422, 'Please fill in the form.');
if ($name === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || ($phone === '' && $wc === '')) kn_fail(422, 'Please fill in the form.');

if (kn_f('again') !== '1') {
  $ep = getenv('KN_LEADS_ENDPOINT') ?: '';
  if ($ep === '') {
    $lt = @file_get_contents(__DIR__ . '/../lead-tracker.js');
    if ($lt && preg_match("/LEADS_ENDPOINT = '([^']+)'/", $lt, $m)) $ep = $m[1];
  }
  $ua = $_SERVER['HTTP_USER_AGENT'] ?? '';
  $lead = json_encode([
    'type' => 'Quick Enquiry', 'source' => 'KNRE website', 'page' => 'Area guide: ' . $area, 'button' => 'Area guide PDF download',
    'name' => $name, 'code' => $code, 'phone' => $phone, 'email' => $email, 'area' => $area,
    'look' => 'Free ' . $area . ' guide (PDF)' . ($wc !== '' ? ' · WeChat/LINE: ' . $wc : ''),
    'message' => $wc !== '' ? 'WeChat/LINE: ' . $wc : '', 'lang' => kn_f('lang', 10),
    'device' => preg_match('/iPad|Tablet/i', $ua) ? 'Tablet' : (preg_match('/Mobi|Android|iPhone/i', $ua) ? 'Mobile' : 'Desktop'),
    'referrer' => kn_f('ref', 300), 'url' => kn_f('page_url', 300),
  ], JSON_UNESCAPED_UNICODE);
  if ($ep && function_exists('curl_init')) {
    $c = curl_init($ep);
    curl_setopt_array($c, [CURLOPT_POST => true, CURLOPT_POSTFIELDS => $lead, CURLOPT_HTTPHEADER => ['Content-Type: text/plain'],
      CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_TIMEOUT => 8]);
    @curl_exec($c);
  } elseif ($ep) {
    @file_get_contents($ep, false, stream_context_create(['http' => ['method' => 'POST', 'header' => "Content-Type: text/plain\r\n", 'content' => $lead, 'timeout' => 8]]));
  }
}
header('Content-Type: application/pdf');
header('Content-Disposition: attachment; filename="KNRE-' . $slug . '-guide.pdf"');
header('Content-Length: ' . filesize($file));
header('Cache-Control: private, no-store');
readfile($file);
